163	    /**
164	     * Run the simulation from its current state for the given number of steps.
165	     * Stop before the given number of steps if it ceases to be viable.
166	     * @param numSteps The number of steps to run for.
167	     */
168	    public void simulate(int numSteps)
169	    {
170	        playingSimulation = true;
171	        remainingSteps = numSteps;
172	
173	        int backupCounter = 1;
174	        while(playingSimulation){
175	            for(int step = 1; step <= numSteps && isViable(); step++) {
176	                simulateOneStep();
177	                backupCounter++;
178	//            delay(60);   // uncomment this to run more slowly
179	            }
180	            if(!isViable()){
181	                // System.out.println("STEPS COMPLETED: "+backupCounter);
182	                // uncomment this while optimizing for population stability
183	                Thread.currentThread().interrupt();
184	                if(backupCounter > SimulationInfo.HIGHEST_STEPS){
185	                    // If multiple instances of the simulation are created in the same session (for testing),
186	                    // the fields in SimulationInfo can be used for optimizing the default probabilities
187	                    SimulationInfo.HIGHEST_STEPS = backupCounter;
188	                    SimulationInfo.HIGHEST_STEP_PROBS = config.getPopulationRates();
189	                }
190	                playingSimulation = false;
191	                break;
192	            }
193	        }
194	        remainingSteps = numSteps - backupCounter;
195	    }
