197	    /**
198	     * Run the simulation from its current state for a single step.
199	     * Iterate over the whole field updating the state of each
200	     * organism.
201	     */
202	    public void simulateOneStep()
203	    {
204	        if(!playingSimulation){ return; }
205	        step++;
206	        environmentController.advance(step);
207	
208	
209	        // Provide space for newborn animals.
210	        List<Actor> newActors = new ArrayList<>();
211	        // Let all actors act.
212	        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
213	            Actor actor = it.next();
214	            if(actor instanceof Animal){
215	               if(((Animal) actor).isAwake(environment)) {
216	                   if(((Animal) actor).isDiseased() && ((Animal) actor).getDisease().getPropagationRate() <= rand.nextDouble()) {
217	                       ((Animal) actor).setDead();
218	                   }
219	                   actor.act(newActors, environment);
220	               }
221	            }
222	            else {
223	                actor.act(newActors, environment);
224	            }
225	
226	            if(actor instanceof Plant){
227	                if(step % ((Plant) actor).STEPS_PER_STAGE()==0){
228	                    ((Plant) actor).incrementGrowth();
229	                }
230	            }
231	
232	            if(! actor.isAlive()) {
233	                it.remove();
234	            }
235	
236	
237	
238	        }
239	        actors.addAll(newActors);
240	        plantGrassInPatches();
241	
242	        notifyPopulationChanged();
243	        notifyStepCompleted();
244	    }
