246	    /**
247	     * Randomly generate grass in free patches on the field, only if it is raining
248	     */
249	    private void plantGrassInPatches(){
250	        // new grass is randomly added in patches
251	        double grassRate = config.getPopulationRate(Grass.class);
252	        for(Location location:field.getRandomFreePatches(grassRate)){
253	            if(rand.nextDouble() <= grassRate && environmentController.isRaining()) {
254	                Grass grass = new Grass(field, location);
255	                actors.add(grass);
256	            }
257	        }
258	    }
