317	    private Actor createInitialActor(Location location)
318	    {
319	        Animal.Gender sex = Randomizer.getRandomSex();
320	        for(Map.Entry<Class<?>, ActorFactory> entry : actorFactories.entrySet()) {
321	            if(rand.nextDouble() <= getCreationProbability(entry.getKey())) {
322	                return entry.getValue().create(location, sex);
323	            }
324	        }
325	        return null;
326	    }
